// Original — Frictionborn Motion
"use client";

import { useEffect, useRef, useCallback } from "react";
import { createSurface, type Surface } from "@frictionborn/runtime/gl";
import { useFrame, useFrameGuard } from "@frictionborn/runtime";
import { vertexShaderSource, fragmentShaderSource } from "./noise-field.glsl";

export interface NoiseFieldGLProps {
  colors: [[number, number, number], [number, number, number], [number, number, number]];
  speed?: number;
  scale?: number;
  intensity?: number;
  paused?: boolean;
  time?: number;
  tier?: number;
  suspended?: boolean;
  onContextLost?: () => void;
  onContextRestored?: () => void;
  onDowngrade?: () => void;
}

export default function NoiseFieldGL({
  colors,
  speed = 1.0,
  scale = 1.8,
  intensity = 1.0,
  paused = false,
  time,
  tier = 3,
  suspended = false,
  onContextLost,
  onContextRestored,
  onDowngrade,
}: NoiseFieldGLProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const surfaceRef = useRef<Surface | null>(null);
  const programRef = useRef<WebGLProgram | null>(null);
  const uniformsRef = useRef<{
    resolution?: WebGLUniformLocation;
    time?: WebGLUniformLocation;
    speed?: WebGLUniformLocation;
    scale?: WebGLUniformLocation;
    intensity?: WebGLUniformLocation;
    octaves?: WebGLUniformLocation;
    colorBg?: WebGLUniformLocation;
    colorPrimary?: WebGLUniformLocation;
    colorAccent?: WebGLUniformLocation;
  }>({});
  const timeRef = useRef<number>(time ?? 0);
  const colorsRef = useRef(colors);
  const onContextLostRef = useRef(onContextLost);
  const onContextRestoredRef = useRef(onContextRestored);

  useEffect(() => {
    colorsRef.current = colors;
    onContextLostRef.current = onContextLost;
    onContextRestoredRef.current = onContextRestored;
  });

  const maxDpr = tier >= 3 ? 2.0 : 1.5;
  const renderScale = tier >= 3 ? 1.0 : 0.75;
  const octaves = tier >= 3 ? 4 : 2;

  const renderFrame = useCallback((currentTime: number) => {
    const surface = surfaceRef.current;
    const program = programRef.current;
    if (!surface || !program) return;

    const gl = surface.gl;
    const u = uniformsRef.current;

    gl.useProgram(program);

    if (u.resolution) {
      gl.uniform2f(u.resolution, gl.drawingBufferWidth, gl.drawingBufferHeight);
    }
    if (u.time) {
      gl.uniform1f(u.time, currentTime);
    }
    if (u.speed) {
      gl.uniform1f(u.speed, speed);
    }
    if (u.scale) {
      gl.uniform1f(u.scale, scale);
    }
    if (u.intensity) {
      gl.uniform1f(u.intensity, intensity);
    }
    if (u.octaves) {
      gl.uniform1i(u.octaves, octaves);
    }

    const currentColors = colorsRef.current;
    if (u.colorBg) {
      gl.uniform3f(u.colorBg, currentColors[0][0], currentColors[0][1], currentColors[0][2]);
    }
    if (u.colorPrimary) {
      gl.uniform3f(u.colorPrimary, currentColors[1][0], currentColors[1][1], currentColors[1][2]);
    }
    if (u.colorAccent) {
      gl.uniform3f(u.colorAccent, currentColors[2][0], currentColors[2][1], currentColors[2][2]);
    }

    surface.draw();
  }, [speed, scale, intensity, octaves]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const canvas = document.createElement("canvas");
    canvas.setAttribute("aria-hidden", "true");
    canvas.style.position = "absolute";
    canvas.style.inset = "0";
    canvas.style.width = "100%";
    canvas.style.height = "100%";
    canvas.style.display = "block";
    canvas.style.pointerEvents = "none";
    canvas.style.zIndex = "2"; // Above poster (z: 1), below scrim (z: 3)
    container.appendChild(canvas);

    function setupProgram(surface: ReturnType<typeof createSurface>) {
      const gl = surface.gl;
      const program = surface.createProgram(vertexShaderSource, fragmentShaderSource);
      programRef.current = program;

      uniformsRef.current = {
        resolution: gl.getUniformLocation(program, "u_resolution") || undefined,
        time: gl.getUniformLocation(program, "u_time") || undefined,
        speed: gl.getUniformLocation(program, "u_speed") || undefined,
        scale: gl.getUniformLocation(program, "u_scale") || undefined,
        intensity: gl.getUniformLocation(program, "u_intensity") || undefined,
        octaves: gl.getUniformLocation(program, "u_octaves") || undefined,
        colorBg: gl.getUniformLocation(program, "u_color_bg") || undefined,
        colorPrimary: gl.getUniformLocation(program, "u_color_primary") || undefined,
        colorAccent: gl.getUniformLocation(program, "u_color_accent") || undefined,
      };
    }

    try {
      const surface = createSurface(canvas, {
        maxDpr,
        scale: renderScale,
        onContextLost: () => {
          canvas.style.display = "none";
          onContextLostRef.current?.();
        },
        onContextRestored: () => {
          canvas.style.display = "block";
          if (surfaceRef.current) {
            setupProgram(surfaceRef.current);
            renderFrame(timeRef.current);
          }
          onContextRestoredRef.current?.();
        },
      }); // @frictionborn-guard

      surfaceRef.current = surface;
      setupProgram(surface);

      // Draw initial frame immediately
      renderFrame(timeRef.current);
    } catch (err) {
      console.warn("NoiseField WebGL2 initialization failed; falling back to poster", err);
      if (surfaceRef.current) {
        surfaceRef.current.dispose(); // @frictionborn-guard
        surfaceRef.current = null;
      }
      onContextLostRef.current?.();
    }

    return () => {
      if (surfaceRef.current) {
        surfaceRef.current.dispose(); // @frictionborn-guard
        surfaceRef.current = null;
      }
      canvas.remove();
    };
  }, [maxDpr, renderScale, renderFrame]);

  // Frame rate monitoring and automated downgrade
  useFrameGuard({ onDowngrade: () => onDowngrade?.(), active: !paused && !suspended }); // @frictionborn-guard

  // Animation loop subscribed via shared runtime useFrame (never raw rAF)
  useFrame(
    ({ dt }) => {
      if (time !== undefined) {
        timeRef.current = time;
      } else {
        timeRef.current += (dt * 0.001) * speed;
      }
      renderFrame(timeRef.current);
    },
    { active: !paused && !suspended } // @frictionborn-guard
  );

  return (
    <div
      ref={containerRef}
      aria-hidden="true"
      style={{
        position: "absolute",
        inset: 0,
        width: "100%",
        height: "100%",
        overflow: "hidden",
        pointerEvents: "none",
        zIndex: 2,
        visibility: suspended ? "hidden" : "visible",
      }}
    />
  );
}

// Source: https://github.com/stegu/webgl-noise — MIT — Copyright (C) 2011 Ashima Arts, Stefan Gustavson
// Adaptation & composition: Original — Frictionborn Motion
export const vertexShaderSource = `#version 300 es
in vec2 position;
out vec2 v_uv;

void main() {
  v_uv = (position + 1.0) * 0.5;
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

export const fragmentShaderSource = `#version 300 es
precision highp float;

in vec2 v_uv;
out vec4 fragColor;

uniform vec2 u_resolution;
uniform float u_time;
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform int u_octaves;
uniform vec3 u_color_bg;
uniform vec3 u_color_primary;
uniform vec3 u_color_accent;

// --- Stefan Gustavson / Ashima Arts 2D Simplex Noise (MIT License) ---
vec3 mod289(vec3 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec2 mod289(vec2 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec3 permute(vec3 x) {
  return mod289(((x * 34.0) + 1.0) * x);
}

float snoise(vec2 v) {
  const vec4 C = vec4(
    0.211324865405187,   // (3.0 - sqrt(3.0)) / 6.0
    0.366025403784439,   // 0.5 * (sqrt(3.0) - 1.0)
   -0.577350269189626,   // -1.0 + 2.0 * C.x
    0.024390243902439    // 1.0 / 41.0
  );

  vec2 i  = floor(v + dot(v, C.yy));
  vec2 x0 = v - i + dot(i, C.xx);

  vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;

  i = mod289(i);
  vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));

  vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
  m = m * m;
  m = m * m;

  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;

  m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);

  vec3 g;
  g.x  = a0.x  * x0.x  + h.x  * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}
// --- End simplex noise primitive ---

// Original Frictionborn multi-octave kinetic flow composition
const mat2 FLOW_ROT1 = mat2(0.80,  0.60, -0.60,  0.80);
const mat2 FLOW_ROT2 = mat2(0.70, -0.71,  0.71,  0.70);

float flowField(vec2 p, float t, int octaves) {
  float val = 0.0;
  float amp = 0.52;
  vec2 coord = p;

  // Primary base layer
  val += amp * (snoise(coord + vec2(t * 0.12, -t * 0.08)) * 0.5 + 0.5);
  coord = FLOW_ROT1 * coord * 1.95 + vec2(1.4, 2.7);
  amp *= 0.50;

  // Secondary layer
  val += amp * (snoise(coord + vec2(-t * 0.15, t * 0.18)) * 0.5 + 0.5);
  coord = FLOW_ROT2 * coord * 2.05 + vec2(3.1, 1.6);
  amp *= 0.48;

  // High-detail octaves active in Tier 3
  if (octaves >= 3) {
    val += amp * (snoise(coord + vec2(t * 0.22, t * 0.11)) * 0.5 + 0.5);
    coord = FLOW_ROT1 * coord * 2.10 + vec2(0.9, 4.3);
    amp *= 0.45;
  }
  if (octaves >= 4) {
    val += amp * (snoise(coord - vec2(t * 0.18, t * 0.25)) * 0.5 + 0.5);
  }

  return val;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_resolution.xy;
  vec2 aspect = vec2(u_resolution.x / min(u_resolution.x, u_resolution.y),
                     u_resolution.y / min(u_resolution.x, u_resolution.y));
  vec2 p = (v_uv - 0.5) * aspect;

  float scale = u_scale > 0.0 ? u_scale : 1.8;
  p *= scale;

  float t = u_time * (u_speed > 0.0 ? u_speed : 0.4);
  int octaves = u_octaves > 0 ? u_octaves : 4;

  // Original advective warp: sample flow velocity field to advect sample coordinates
  vec2 drift = vec2(
    snoise(p * 0.75 + vec2(t * 0.08, 1.2)),
    snoise(p * 0.75 + vec2(3.4, t * 0.09))
  );

  vec2 warpedP = p + drift * 0.38;
  float intensity = u_intensity > 0.0 ? u_intensity : 1.0;
  float n = flowField(warpedP, t, octaves) * intensity;

  // Wide contrast remapping curve to eliminate muddy mid-range
  float tPrimary = smoothstep(0.20, 0.65, n);
  float tAccent  = smoothstep(0.55, 0.92, n);

  // Blend from background base -> primary -> accent
  vec3 col = mix(u_color_bg, u_color_primary, tPrimary * 0.85);
  col = mix(col, u_color_accent, tAccent * 0.90);

  // Soft vignette grounding edges into background token
  float vignette = smoothstep(1.3, 0.3, length((v_uv - 0.5) * aspect));
  col = mix(u_color_bg, col, clamp(vignette + 0.15, 0.0, 1.0));

  fragColor = vec4(col, 1.0);
}
`;

// Original — Frictionborn Motion
"use client";

import React, { useState, useEffect, useRef, useCallback, useId, Suspense, lazy, useImperativeHandle } from "react";
import {
  useCapability,
  useHydrated,
  useReducedMotion,
  useInView,
  resolveCssColor,
  paletteVars,
  type PaletteName,
  glBudget,
  type Lease,
} from "@frictionborn/runtime";

const NoiseFieldGL = lazy(() => import("./noise-field.gl"));

export interface NoiseFieldProps extends React.HTMLAttributes<HTMLDivElement> {
  colors?: [string, string, string];
  /** Colours from a palette (DESIGN.md A8): `fire` | `ice` | `neon` | `mono` | `custom` (reads `--fb-heat-0..4`). Overrides `colors`; leave it out to keep the host's tokens. */
  palette?: PaletteName;
  speed?: number;
  scale?: number;
  intensity?: number;
  scrim?: boolean;
  paused?: boolean;
  time?: number;
  maxTier?: number;
  reducedMotion?: boolean;
  ref?: React.Ref<HTMLDivElement>;
  children?: React.ReactNode;
}

/** round 4: the palette's background, hot and bright colours (DESIGN.md A8); a preset sets them on the root, `custom` reads the page's */
const HEAT_COLORS: [string, string, string] = ["var(--fb-heat-0)", "var(--fb-heat-2)", "var(--fb-heat-3)"];

// Stable default: a fresh array each render would re-trigger the colour resolver forever
const DEFAULT_COLORS: [string, string, string] = [
  "var(--background, Canvas)",
  "var(--primary, CanvasText)",
  "var(--accent, GrayText)",
];

export function NoiseField({
  colors: colorsProp = DEFAULT_COLORS,
  palette,
  speed = 1.0,
  scale = 1.8,
  intensity = 1.0,
  scrim = true,
  paused = false,
  time,
  maxTier = 3,
  reducedMotion: propReduced,
  ref,
  className = "",
  style,
  children,
  ...props
}: NoiseFieldProps) {
  const colors = palette ? HEAT_COLORS : colorsProp;
  const containerRef = useRef<HTMLDivElement | null>(null);
  const uid = useId();
  const hydrated = useHydrated(); // @frictionborn-guard
  const cap = useCapability(); // @frictionborn-guard
  const systemReduced = useReducedMotion(); // @frictionborn-guard
  const reduced = propReduced !== undefined ? propReduced : systemReduced; // @frictionborn-guard
  const inView = useInView(containerRef); // @frictionborn-guard

  const [hasLease, setHasLease] = useState(false);
  const leaseRef = useRef<Lease | null>(null);
  const instanceId = useRef("noise-field-" + uid);
  const [contextLost, setContextLost] = useState(false);
  const [glKey, setGlKey] = useState(0);
  const [downgrades, setDowngrades] = useState(0);
  const computedTier = Math.min(cap.tier, maxTier);
  const effectiveTier = hydrated ? Math.max(0, computedTier - downgrades) : 0;

  // Resolved RGB arrays for WebGL uniforms
  const [rgbColors, setRgbColors] = useState<[[number, number, number], [number, number, number], [number, number, number]]>([
    [0.05, 0.06, 0.08],
    [0.98, 0.57, 0.24],
    [0.23, 0.51, 0.96],
  ]);

  const c0 = colors[0];
  const c1 = colors[1];
  const c2 = colors[2];
  const updateResolvedColors = useCallback(() => {
    const el = containerRef.current;
    const r0 = resolveCssColor(el, c0) ?? [0.05, 0.06, 0.08];
    const r1 = resolveCssColor(el, c1) ?? [0.98, 0.57, 0.24];
    const r2 = resolveCssColor(el, c2) ?? [0.23, 0.51, 0.96];
    setRgbColors([r0, r1, r2]);
  }, [c0, c1, c2]);

  // Resolve colors on mount, prop change, and HTML theme attribute mutations
  useEffect(() => {
    updateResolvedColors();

    if (typeof MutationObserver === "undefined") return;
    const observer = new MutationObserver(() => {
      updateResolvedColors();
    });
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "data-theme", "data-mode", "style"],
    });
    return () => observer.disconnect();
  }, [updateResolvedColors]);

  // Context lease acquisition (PRD 6.0 + 6.1 + Decision 19: reduced motion = no WebGL)
  useEffect(() => {
    // Decision 19: Reduced motion gets static poster only (no WebGL context)
    const shouldAcquire = hydrated && inView && effectiveTier >= 2 && !reduced;

    if (!shouldAcquire) {
      if (leaseRef.current) {
        leaseRef.current.release(); // @frictionborn-guard
        leaseRef.current = null;
        setHasLease(false);
      }
      return;
    }

    const tryAcquire = () => {
      if (leaseRef.current) return;
      const newLease = glBudget.acquire({
        id: instanceId.current,
        priority: 1,
        onEvict: () => {
          leaseRef.current = null;
          setHasLease(false);
        },
      }); // @frictionborn-guard
      if (newLease) {
        leaseRef.current = newLease;
        setHasLease(true);
        setContextLost(false);
        setGlKey((k) => k + 1);
      }
    };

    tryAcquire();
    return glBudget.subscribe(() => {
      if (!leaseRef.current) tryAcquire();
    });
  }, [hydrated, inView, effectiveTier, contextLost, reduced]);

  useEffect(() => {
    return () => {
      if (leaseRef.current) {
        leaseRef.current.release(); // @frictionborn-guard
        leaseRef.current = null;
      }
    };
  }, []);

  const handleDowngrade = useCallback(() => {
    setDowngrades((prev) => prev + 1); // @frictionborn-guard
  }, []);

  const handleContextLost = useCallback(() => {
    setContextLost(true); // @frictionborn-guard
  }, []);

  const handleContextRestored = useCallback(() => {
    setContextLost(false); // @frictionborn-guard
    setGlKey((k) => k + 1);
  }, []);

  // Poster matching the shader's palette & visual flow (CLS 0)
  const posterStyle: React.CSSProperties = {
    position: "absolute",
    inset: 0,
    width: "100%",
    height: "100%",
    background: `radial-gradient(circle at 35% 25%, color-mix(in srgb, ${colors[1]} 35%, transparent) 0%, transparent 65%), radial-gradient(circle at 75% 70%, color-mix(in srgb, ${colors[2]} 30%, transparent) 0%, transparent 60%), radial-gradient(circle at 50% 50%, color-mix(in srgb, ${colors[1]} 15%, ${colors[2]} 15%) 0%, transparent 75%), ${colors[0]}`,
    zIndex: 1,
  };

  // Theme-aware scrim using host background token to guarantee >= 4.5:1 text contrast
  const scrimStyle: React.CSSProperties = {
    position: "absolute",
    inset: 0,
    zIndex: 3,
    pointerEvents: "none",
    background: `radial-gradient(circle at center, color-mix(in srgb, ${colors[0]} 25%, transparent) 0%, color-mix(in srgb, ${colors[0]} 80%, transparent) 100%)`,
  };

  useImperativeHandle(ref, () => containerRef.current as HTMLDivElement);

  const canRenderWebGL = hasLease && !reduced && effectiveTier >= 2;

  return (
    <div
      ref={containerRef}
      data-frictionborn-item="noise-field"
      data-tier={effectiveTier}
      data-in-view={inView}
      data-reduced-motion={reduced}
      className={`relative w-full h-full min-h-[300px] overflow-hidden ${className}`}
      style={{ ...(palette ? paletteVars(palette) : null), backgroundColor: colors[0], ...style }}
      {...props}
    >
      {/* 1. Server-rendered CSS gradient poster always present as fallback (CLS 0) */}
      <div data-frictionborn-poster="true" style={posterStyle} aria-hidden="true" />

      {/* 2. WebGL canvas rendered client-side only when lease granted and not reduced-motion */}
      {canRenderWebGL && (
        <Suspense fallback={null}>
          <NoiseFieldGL
            key={glKey}
            suspended={contextLost}
            colors={rgbColors}
            speed={speed}
            scale={scale}
            intensity={intensity}
            paused={paused}
            time={time}
            tier={effectiveTier}
            onContextLost={handleContextLost}
            onContextRestored={handleContextRestored}
            onDowngrade={handleDowngrade}
          />
        </Suspense>
      )}

      {/* 3. Theme-aware scrim layer preserving WCAG AA contrast >= 4.5:1 for overlaid text */}
      {scrim && <div style={scrimStyle} aria-hidden="true" />}

      {/* 4. Children slot */}
      {children && (
        <div style={{ position: "relative", zIndex: 4, width: "100%", height: "100%" }}>
          {children}
        </div>
      )}
    </div>
  );
}

export default NoiseField;

